INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(35411, 'Matthew 12:24', 'Matthew', 12, 24, 'خو کله چې فریسیانو دا واورېدل نو ویې ویل: «دا سړی د پېریانو د مشر بعلزبول په مرسته پېریان وباسي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew12_verse_24.mp3', '', 1761754199, 1761754199),
(35412, 'Matthew 12:25', 'Matthew', 12, 25, 'عیسی پوهېده چې د هغوی په ذهن کې څه ګرځي، نو هغوی ته یې وویل: «هره پاچاهي چې په خپل منځ کې په ډلو ووېشل شي او یو د بل سره وجنګیږي، هغه له منځه ځي او هر ښار او هره کورنۍ چې په خپلو کې یو د بل په خلاف شي نو هغه به پاتې نه شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew12_verse_25.mp3', '', 1761754199, 1761754199),
(35413, 'Matthew 12:26', 'Matthew', 12, 26, 'که چېرې شیطان، شیطان وباسي نو بیا خو شیطان په خپله د خپل ځان په خلاف شو، نو د هغه پاچاهي به څنګه پاتې شي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew12_verse_26.mp3', '', 1761754199, 1761754199),
(35414, 'Matthew 12:27', 'Matthew', 12, 27, 'که چېرې زه د بعلزبول په مرسته پېریان وباسم، نو ستاسو خپل پیروان یې د چا په مرسته وباسي؟ نو هغوی به ستاسو په هکله قضاوت وکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew12_verse_27.mp3', '', 1761754199, 1761754199),
(35415, 'Matthew 12:28', 'Matthew', 12, 28, 'خو که چېرې زه د خدای د روح په مرسته پېریان وباسم، نو بیا پوه شئ چې د خدای پاچاهي تاسو ته راغلې ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew12_verse_28.mp3', '', 1761754199, 1761754199),
(35416, 'Matthew 12:29', 'Matthew', 12, 29, 'یا څنګه څوک کولای شي چې د یو زورور سړي کور ته ورننوځي او د هغه د کور سامان لوټ کړي، ترڅو چې لومړی هغه سړی وتړي او بیا یې کور لوټ کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew12_verse_29.mp3', '', 1761754199, 1761754199),
(35417, 'Matthew 12:30', 'Matthew', 12, 30, 'څوک چې زما سره نه دی، هغه زما په خلاف دی او څوک چې زما سره د خلکو په راټولولو کې مرسته نه کوي، هغوی خواره واره کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew12_verse_30.mp3', '', 1761754199, 1761754199),
(35418, 'Matthew 12:31', 'Matthew', 12, 31, 'نو له دې امله زه تاسو ته وایم چې د انسان هره ګناه او کفر ویل به وبخښل شي، خو که چېرې د روح القدس په خلاف کفر وویل شي هغه به ونه بخښل شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew12_verse_31.mp3', '', 1761754199, 1761754199),
(35419, 'Matthew 12:32', 'Matthew', 12, 32, 'هرڅوک چې د انسان د زوی په خلاف څه ووایي هغه به وبخښل شي، خو که چېرې څوک د روح القدس په خلاف څه ووایي هغه به ونه بخښل شي، نه په دې نړۍ کې او نه په راتلونکې نړۍ کې.» ونه او د هغې مېوه (لوقا ۶‏:‌۴۳‌‏-‌۴۵)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew12_verse_32.mp3', '', 1761754199, 1761754199),
(35420, 'Matthew 12:33', 'Matthew', 12, 33, 'عیسی زیاته کړه: «یوه ونه د هغې د مېوې څخه پېژندل کیږي. که ونه ښه وي، نو مېوه به یې هم ښه وي. که ونه خرابه وي، نو مېوه به یې هم خرابه وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew12_verse_33.mp3', '', 1761754199, 1761754199),
(35421, 'Matthew 12:34', 'Matthew', 12, 34, 'ای د مارانو بچیانو! تاسو چې داسې بدکاره خلک یئ نو بیا څنګه کولای شئ ښې خبرې وکړئ؟ ځکه کومې خبرې چې په زړه کې وي هغه په خوله راوځي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew12_verse_34.mp3', '', 1761754199, 1761754199),
(35422, 'Matthew 12:35', 'Matthew', 12, 35, 'ښه سړی د خپلې ښې خزانې څخه چې په هغه کې ده، ښه شیان راوباسي او بد سړی د خپلې بدې خزانې څخه بد شیان راوباسي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew12_verse_35.mp3', '', 1761754199, 1761754199),
(35423, 'Matthew 12:36', 'Matthew', 12, 36, 'زه تاسو ته وایم چې د قیامت په ورځ به هرڅوک د خپلو بېځایه خبرو چې کړي یې دي ځواب وایي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew12_verse_36.mp3', '', 1761754199, 1761754199),
(35424, 'Matthew 12:37', 'Matthew', 12, 37, 'ځکه چې تاسو به په خپلو خبرو بې‌ګناه او یا ګناهکار وګڼل شئ.» د شریعت عالمان او فریسیان معجزه غواړي (مرقوس ۸‏:‌۱۱‌‏-‌۱۲ او لوقا ۱۱‏:‌۲۹‌‏-‌۳۲)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew12_verse_37.mp3', '', 1761754199, 1761754199),
(35425, 'Matthew 12:38', 'Matthew', 12, 38, 'بیا د شریعت ځینو عالمانو او فریسیانو عیسی ته وویل: «ای استاذه، مونږ غواړو چې یوه معجزه راته وښایې.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew12_verse_38.mp3', '', 1761754199, 1761754199),
(35426, 'Matthew 12:39', 'Matthew', 12, 39, 'خو عیسی په ځواب کې وویل: «د دې زمانې بدکاره او بې‌ایمانه خلک یوه معجزه غواړي، خو یوازېنۍ معجزه چې هغوی ته به وښودل شي هغه د یونس نبي معجزه ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew12_verse_39.mp3', '', 1761754199, 1761754199),
(35427, 'Matthew 12:40', 'Matthew', 12, 40, 'لکه څنګه چې یونس درې ورځې او درې شپې د یو لوی ماهي په خېټه کې تېرې کړې، نو همداسې به د انسان زوی درې ورځې او درې شپې د ځمکې په تل کې تېرې کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew12_verse_40.mp3', '', 1761754199, 1761754199),
(35428, 'Matthew 12:41', 'Matthew', 12, 41, 'د قیامت په ورځ به د نینوا خلک راپورته شي او د دې زمانې خلک به ملامته کړي، ځکه چې هغوی د یونس د وعظ په اورېدلو سره توبه وویستله. خو ګورئ اوس چې څوک دلته دی هغه د یونس نه لوی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew12_verse_41.mp3', '', 1761754199, 1761754199),
(35429, 'Matthew 12:42', 'Matthew', 12, 42, 'د شیبا د هېواد ملکه به د قیامت په ورځ راپورته شي او د دې زمانې خلک به ملامته کړي، ځکه چې هغه د نړۍ د بل سر نه راغلې وه چې د سلیمان د حکمت څخه ډکې خبرې واوري. خو ګورئ، اوس دلته یو څوک شته چې د سلیمان نه لوی دی. د پېریانو بېرته راتلل (لوقا ۱۱‏:‌۲۴‌‏-‌۲۶)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew12_verse_42.mp3', '', 1761754199, 1761754199),
(35430, 'Matthew 12:43', 'Matthew', 12, 43, 'کله چې د یو سړي څخه پېری راوځي، نو په دښتو کې سرګردانه ګرځي او د ارام کولو دپاره ځای لټوي، خو کله چې داسې ځای پیدا نه کړي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew12_verse_43.mp3', '', 1761754199, 1761754199),
(35431, 'Matthew 12:44', 'Matthew', 12, 44, 'نو د خپل ځان سره وایي: ‹زه به بېرته هغه کور ته لاړ شم چې ورڅخه راوتلی وم. کله چې بېرته راشي نو هغه کور خالي، جارو شوی او منظم وویني.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew12_verse_44.mp3', '', 1761754199, 1761754199),
(35432, 'Matthew 12:45', 'Matthew', 12, 45, 'بیا هغه لاړ شي او د ځان څخه ډېر بد نور اووه پېریان راولي، هغوی ټول راشي او په هغه کس کې ورننوځي او هلته اوسیږي. او د هغه حال له مخکې څخه هم خراب شي. نو د دې زمانې د بدکاره خلکو به هم همدا حال وي.›» د عیسی مور او ورونه (مرقوس ۳‏:‌۳۱‌‏-‌۳۵ او لوقا ۸‏:‌۱۹‌‏-‌۲۱)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew12_verse_45.mp3', '', 1761754199, 1761754199),
(35433, 'Matthew 12:46', 'Matthew', 12, 46, 'عیسی لا د خلکو سره خبرې کولې چې مور او ورونه یې راغلل او دباندې ولاړ وو او غوښتل یې چې د هغه سره خبرې وکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew12_verse_46.mp3', '', 1761754199, 1761754199),
(35434, 'Matthew 12:47', 'Matthew', 12, 47, 'بیا یو چا عیسی ته وویل: «ستا مور او ورونه دباندې ولاړ دي او غواړي ستا سره خبرې وکړي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew12_verse_47.mp3', '', 1761754199, 1761754199),
(35435, 'Matthew 12:48', 'Matthew', 12, 48, 'عیسی په ځواب کې وویل: «زما مور څوک ده؟ او زما ورونه څوک دي؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew12_verse_48.mp3', '', 1761754199, 1761754199),
(35436, 'Matthew 12:49', 'Matthew', 12, 49, 'بیا هغه خپلو شاګردانو ته اشاره وکړه او ویې ویل: «دا زما مور او زما ورونه دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew12_verse_49.mp3', '', 1761754199, 1761754199),
(35437, 'Matthew 12:50', 'Matthew', 12, 50, 'ځکه هرڅوک چې زما د اسماني پلار اراده پوره کوي، هغه زما ورور، زما خور او زما مور ده.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew12_verse_50.mp3', '', 1761754199, 1761754199),
(35438, 'Matthew 25:1', 'Matthew', 25, 1, 'عیسی زیاته کړه: «په هغه وخت کې به اسماني پاچاهي د هغو لسو پېغلو په شان وي چې خپل څراغونه یې واخیستل او د زوم لیدلو ته لاړلې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew25_verse_1.mp3', '', 1761754199, 1761754199),
(35439, 'Matthew 25:2', 'Matthew', 25, 2, 'په هغوی کې پنځه یې کم‌عقلې وې او پنځه یې هوښیارې وې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew25_verse_2.mp3', '', 1761754199, 1761754199),
(35440, 'Matthew 25:3', 'Matthew', 25, 3, 'کم‌عقلو انجونو خپل څراغونه د ځان سره واخیستل، خو تېل یې ورسره وانخیستل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew25_verse_3.mp3', '', 1761754199, 1761754199),
(35441, 'Matthew 25:4', 'Matthew', 25, 4, 'خو هوښیارو انجونو د خپلو څراغونو سره د تېلو نه ډک بوتلونه هم د ځان سره واخیستل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew25_verse_4.mp3', '', 1761754199, 1761754199),
(35442, 'Matthew 25:5', 'Matthew', 25, 5, 'کله چې زوم د راتللو په وخت کې ځنډ شو، نو هغوی ټولو ته خوب ورغی او ویدې شوې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew25_verse_5.mp3', '', 1761754199, 1761754199),
(35443, 'Matthew 25:6', 'Matthew', 25, 6, 'خو په نیمه شپه کې چیغې شوې: ‹ګورئ زوم راروان دی. راځئ چې مخې ته یې ورشو.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew25_verse_6.mp3', '', 1761754199, 1761754199),
(35444, 'Matthew 25:7', 'Matthew', 25, 7, 'نو ټولې انجونې راپاڅېدلې او خپل څراغونه یې تیار کړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew25_verse_7.mp3', '', 1761754199, 1761754199),
(35445, 'Matthew 25:8', 'Matthew', 25, 8, 'کم‌عقلو انجونو هوښیارو انجونو ته وویل: ‹د خپلو تېلو څخه مونږ ته لږ راکړئ، ځکه چې زمونږ څراغونه مړه کیږي.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew25_verse_8.mp3', '', 1761754199, 1761754199),
(35446, 'Matthew 25:9', 'Matthew', 25, 9, 'هوښیارو انجونو ورته ځواب ورکړ: ‹نه، زمونږ سره دومره تېل نشته چې د ټولو کار ورباندې وشي، دا به ښه وي چې تاسو دوکان ته لاړې شئ او خپل ځان ته تېل واخلئ.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew25_verse_9.mp3', '', 1761754199, 1761754199),
(35447, 'Matthew 25:10', 'Matthew', 25, 10, 'کله چې هغوی د تېلو اخیستلو پسې لاړلې، نو زوم راورسېد. هغه انجونې چې تیارې وې د هغه سره د واده مېلمستیا ته لاړلې او دروازې بندې شوې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew25_verse_10.mp3', '', 1761754199, 1761754199),
(35448, 'Matthew 25:11', 'Matthew', 25, 11, 'وروسته بیا هغه نورې پنځه انجونې راغلې او چیغې یې کړې: ‹ای ښاغلیه! ای ښاغلیه! مونږ ته دروازه خلاصه کړه.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew25_verse_11.mp3', '', 1761754199, 1761754199),
(35449, 'Matthew 25:12', 'Matthew', 25, 12, 'زوم وویل: ‹په یقین سره زه تاسو ته وایم چې تاسو نه پېژنم.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew25_verse_12.mp3', '', 1761754199, 1761754199),
(35450, 'Matthew 25:13', 'Matthew', 25, 13, 'نو بېداره اوسئ، ځکه چې تاسو نه پوهېږئ چې د انسان زوی به په کومه ورځ او په کوم ساعت راځي. د درې نوکرانو مثال (لوقا ۱۹‏:‌۱۱‌‏-‌۲۷)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew25_verse_13.mp3', '', 1761754199, 1761754199),
(35451, 'Matthew 25:14', 'Matthew', 25, 14, 'اسماني پاچاهي د هغه سړي په مثال ده چې غوښتل یې په سفر لاړ شي، نو خپل نوکران یې راوغوښتل او خپل مال او جایداد یې ورته وسپارله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew25_verse_14.mp3', '', 1761754199, 1761754199),
(35452, 'Matthew 25:15', 'Matthew', 25, 15, 'هر یو ته یې د هغوی د توان سره سم یو څه ورکړل. یو ته یې د سرو زرو پنځه کڅوړې ورکړې، بل ته یې دوه د سرو زرو کڅوړې او درېم ته یې د سرو زرو یوه کڅوړه ورکړه. بیا په سفر روان شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew25_verse_15.mp3', '', 1761754199, 1761754199),
(35453, 'Matthew 25:16', 'Matthew', 25, 16, 'هغه نوکر چې د سرو زرو پنځه کڅوړې یې ورته ورکړې وې، سمدلاسه لاړ او کار یې ورباندې پیل کړ او په هغو باندې یې نورې د سرو زرو پنځه کڅوړې وګټلې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew25_verse_16.mp3', '', 1761754199, 1761754199),
(35454, 'Matthew 25:17', 'Matthew', 25, 17, 'همدارنګه هغه نوکر چې د سرو زرو دوه کڅوړې یې درلودلې هغه ورباندې نورې د سرو زرو دوه کڅوړې وګټلې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew25_verse_17.mp3', '', 1761754199, 1761754199),
(35455, 'Matthew 25:18', 'Matthew', 25, 18, 'خو کوم نوکر ته چې د سرو زرو یوه کڅوړه ورکړل شوې وه، هغه لاړ او ځمکه یې وکیندله او د خپل بادار پیسې یې په کې ښخې کړلې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew25_verse_18.mp3', '', 1761754199, 1761754199),
(35456, 'Matthew 25:19', 'Matthew', 25, 19, 'ډېر وخت وروسته د هغو نوکرانو بادار راغی او د هغوی څخه یې حساب وغوښت.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew25_verse_19.mp3', '', 1761754199, 1761754199),
(35457, 'Matthew 25:20', 'Matthew', 25, 20, 'کوم نوکر ته چې د سرو زرو پنځه کڅوړې ورکړل شوې وې راغی او نورې د سرو زرو پنځه کڅوړې یې د ځان سره راوړلې او ویې ویل: ‹باداره، تا ماته د سرو زرو پنځه کڅوړې راکړې وې. اوس ګورئ، ما ورباندې پنځه نورې کڅوړې وګټلې.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew25_verse_20.mp3', '', 1761754199, 1761754199),
(35458, 'Matthew 25:21', 'Matthew', 25, 21, 'بادار یې ورته وویل: ‹شاباس، زما نېک او وفادار نوکره! تا په لږ شي کې خپل اعتبار ثابت کړ. نو زه به تاته نور ډېر کارونه دروسپارم. راشه او د خپل بادار په خوشحالۍ کې شریک شه.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew25_verse_21.mp3', '', 1761754199, 1761754199),
(35459, 'Matthew 25:22', 'Matthew', 25, 22, 'بیا هغه نوکر چې دوه کڅوړې سره زر ورته ورکړل شوي وو، راغی او ویې ویل: ‹باداره! تا ماته دوه کڅوړې راکړې وې. اوس ګورئ! ما ورباندې دوه نورې هم وګټلې.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew25_verse_22.mp3', '', 1761754199, 1761754199),
(35460, 'Matthew 25:23', 'Matthew', 25, 23, 'بادار یې ورته وویل: ‹شاباس، ای نېک او وفاداره نوکره! تا په لږ شي کې خپل اعتبار ثابت کړ، نو زه به تاته نور ډېر کارونه دروسپارم. راشه او د خپل بادار په خوشحالۍ کې شریک شه.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew25_verse_23.mp3', '', 1761754199, 1761754199),
(35461, 'Matthew 25:24', 'Matthew', 25, 24, 'بیا هغه نوکر چې یوه کڅوړه ورته ورکړل شوې وه راغی او ویې ویل: ‹باداره! زه پوهېدم چې ته یو سخت سړی یې، ته هغه فصل رېبې چې کرلی دې نه دی او د هغه ځای حاصل راټولوې چې تخم دې په کې نه دی شیندلی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew25_verse_24.mp3', '', 1761754199, 1761754199),
(35462, 'Matthew 25:25', 'Matthew', 25, 25, 'نو زه ووېرېدم او لاړم او ستا سره زر مې په ځمکه کې ښخ کړل. هغه دا دي، بېرته یې واخله.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew25_verse_25.mp3', '', 1761754199, 1761754199),
(35463, 'Matthew 25:26', 'Matthew', 25, 26, 'خو بادار یې ورته په ځواب کې وویل: ‹ای بېکاره او لټ نوکره! کله چې تاته معلومه وه چې زه هغه فصل رېبم چې کرلی مې نه دی او له هغه ځای څخه حاصل راټولوم چې تخم مې په کې نه دی شیندلی،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew25_verse_26.mp3', '', 1761754199, 1761754199),
(35464, 'Matthew 25:27', 'Matthew', 25, 27, 'نو تا باید زما پیسې صرافانو ته ورکړې وای او کله چې زه بېرته راغلی وم، نو هغه به مې بېرته د سود سره اخیستې وای.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew25_verse_27.mp3', '', 1761754199, 1761754199),
(35465, 'Matthew 25:28', 'Matthew', 25, 28, 'د هغه څخه هغه د سرو زرو کڅوړه واخلئ او هغه چاته یې ورکړئ چې لس کڅوړې ورسره دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew25_verse_28.mp3', '', 1761754199, 1761754199),
(35466, 'Matthew 25:29', 'Matthew', 25, 29, 'ځکه د چا سره چې څه وي هغه ته به نور هم ورکړل شي، ترڅو د هغه سره نورې هم زیاتې شي. خو د چا سره چې څه نه وي، نو څه چې ورسره وي هغه به هم ترې واخیستل شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew25_verse_29.mp3', '', 1761754199, 1761754199),
(35467, 'Matthew 25:30', 'Matthew', 25, 30, 'دا بېکاره نوکر دباندې تیارې ته وغورځوئ یعنې هغه ځای ته چې هلته به خلک ژاړي او خپل غاښونه به چیچي.› د قیامت په ورځ د خلکو د عملونو قضاوت', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew25_verse_30.mp3', '', 1761754199, 1761754199),
(35468, 'Matthew 25:31', 'Matthew', 25, 31, 'کله چې د انسان زوی د خپل جلال سره د ټولو فرښتو سره راشي، نو بیا به هغه په خپل شاهانه تخت باندې کښېني', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew25_verse_31.mp3', '', 1761754199, 1761754199),
(35469, 'Matthew 25:32', 'Matthew', 25, 32, 'او د ټولو قومونو خلک به د هغه په حضور کې راټول شي او هغه به هغوی داسې یو له بل نه بېل کړي لکه څنګه چې شپانه پسونه له وزو نه بېلوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew25_verse_32.mp3', '', 1761754199, 1761754199),
(35470, 'Matthew 25:33', 'Matthew', 25, 33, 'نو په دې ډول به هغه پسونه یعنې نېک خلک خپل ښي لاس ته او وزې یعنې بد خلک خپل چپ لاس ته ځای په ځای کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew25_verse_33.mp3', '', 1761754199, 1761754199),
(35471, 'Matthew 25:34', 'Matthew', 25, 34, 'بیا به پاچا هغو خلکو ته چې د هغه ښي لاس ته دي ووایي چې ای هغو خلکو چې زما د پلار له خوا درته برکت درکړل شوی دی، راشئ او د هغې پاچاهۍ وارثان شئ چې د نړۍ د پیدایښت راهیسې ستاسو دپاره تیاره شوې وه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew25_verse_34.mp3', '', 1761754199, 1761754199),
(35472, 'Matthew 25:35', 'Matthew', 25, 35, 'ځکه کله چې زه وږی وم نو تاسو راته خواړه راکړل، کله چې تږی وم نو اوبه مو راته راکړې، کله چې مسافر وم نو تاسو خپل کور ته بوتلم،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew25_verse_35.mp3', '', 1761754199, 1761754199),
