(35499, 'Luke 4:16', 'Luke', 4, 16, 'بیا عیسی د ناصرې ښار ته، یعنې هغه ځای ته چې هغه په کې لوی شوی ؤ راغی او لکه څنګه چې د هغه عادت ؤ، نو د سبت په ورځ کنیسې ته لاړ. هغه هلته ودرېده چې د خدای کلام ولولي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke4_verse_16.mp3', '', 1761754199, 1761754199),
(35500, 'Luke 4:17', 'Luke', 4, 17, 'او د اشعیا پیغمبر طومار ورته ورکړل شو. هغه یې پرانیست او هغه ځای یې پیدا کړ چې په کې لیکل شوي وو:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke4_verse_17.mp3', '', 1761754199, 1761754199),
(35501, 'Luke 4:18', 'Luke', 4, 18, '«د څښتن روح په ما باندې نازل شوی دی ځکه چې زه یې مسح کړی یم ترڅو غریبانو ته زېری ورسوم هغه زه رالېږلی یم چې اعلان وکړم چې بندیان به ازاد شي ړانده به بینا شي او مظلومان به ازاد شي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke4_verse_18.mp3', '', 1761754199, 1761754199),
(35502, 'Luke 4:19', 'Luke', 4, 19, 'او دا اعلان کړم چې د څښتن د مهربانۍ وخت رارسېدلی دی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke4_verse_19.mp3', '', 1761754199, 1761754199),
(35503, 'Luke 4:20', 'Luke', 4, 20, 'عیسی طومار بند کړ او هغه یې بېرته د کنیسې مسوول کس ته ورکړ او کښېناست. ټولو خلکو په کنیسه کې د هغه خواته سترګې نیولې وې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke4_verse_20.mp3', '', 1761754199, 1761754199),
(35504, 'Luke 4:21', 'Luke', 4, 21, 'عیسی هغوی ته وویل: «نن چې تاسو د خدای د کلام دا لیکنه واورېدله، هغه رښتیا شوه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke4_verse_21.mp3', '', 1761754199, 1761754199),
(35505, 'Luke 4:22', 'Luke', 4, 22, 'هغوی ټولو په هغه باندې ښه وویل او په دې حیران شول چې داسې د فضل خبرې د هغه د خولې څخه راووتلې او ویل یې: «ایا دا د یوسف زوی نه دی؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke4_verse_22.mp3', '', 1761754199, 1761754199),
(35506, 'Luke 4:23', 'Luke', 4, 23, 'عیسی هغوی ته وویل: «بې له شکه چې تاسو به ماته دا متل ووایئ: ‹ای ډاکتره! خپل ځان روغ کړه.› دا به هم راته ووایئ چې کوم کارونه چې تا د کپرناحوم په ښار کې کړي دي او مونږ د هغو په هکله اورېدلي، هماغه کارونه په خپل ښار کې هم وکړه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke4_verse_23.mp3', '', 1761754199, 1761754199),
(35507, 'Luke 4:24', 'Luke', 4, 24, 'عیسی زیاته کړه: «په یقین سره زه تاسو ته دا وایم چې هېڅ پیغمبر په خپل وطن کې چا نه دی منلی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke4_verse_24.mp3', '', 1761754199, 1761754199),
(35508, 'Luke 4:25', 'Luke', 4, 25, 'دا رښتیا دي چې د الیاس پیغمبر په زمانه کې په اسراییلو کې ډېرې کونډې وې. په هغه وخت کې درې نیم کاله بارانونه نه وو شوي او په ټول وطن کې سخته قحطي راغلې وه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke4_verse_25.mp3', '', 1761754199, 1761754199),
(35509, 'Luke 4:26', 'Luke', 4, 26, 'خو الیاس په هغو کونډو کې یوې ته هم د مرستې دپاره ونه لېږل شو، خو یوازې هغې کونډې ته ولېږل شو چې د صیدون د زرفت په سیمه کې وه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke4_verse_26.mp3', '', 1761754199, 1761754199),
(35510, 'Luke 4:27', 'Luke', 4, 27, 'همدارنګه د الیشع نبي په زمانه کې په اسراییلو کې ډېر خلک وو چې د جذام په ناروغۍ اخته وو، خو د هغوی څخه یو هم پاک او روغ نه شو، یوازې نعمان چې سوریایي ؤ، روغ شو.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke4_verse_27.mp3', '', 1761754199, 1761754199);